    { type: 'order', q: '把做预算的步骤按顺序排好', items: ['确认这个月的收入', '搞清固定支出(房租、水电)', '把剩下的钱分配给储蓄和变动支出', '一个月后对比实际支出并调整'], explain: '不知道收入是多少,就没法做任何计划。而最后的调整步骤,才让预算变成一份真正有生命力的计划。' },
    { type: 'quiz', q: '当预算和实际支出对不上时,应该怎么做?', options: ['确认差距,调整下个月的预算', '干脆放弃做预算', '绝不修改最初定的预算', '减少收入'], correct: 0, explain: '预算不是定完就结束了,而是每个月对比、调整的持续过程。' },
    { type: 'quiz', q: '预算一开始就必须做到完美,定下来之后绝对不能改。', options: ['O', 'X'], correct: 1, explain: '每个月对照实际支出不断调整,才是预算正常的使用方式。' }
